import{_ as o,r as s,o as l,c as p,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Translatable - October CMS - 4.x","titleTemplate":false,"description":"Learn how to translate individual model attributes across locales.","frontmatter":{"subtitle":"Learn how to translate individual model attributes across locales."},"headers":[{"level":2,"title":"How It Works","slug":"how-it-works","link":"#how-it-works","children":[]},{"level":2,"title":"Reading Translations","slug":"reading-translations","link":"#reading-translations","children":[]},{"level":2,"title":"Writing Translations","slug":"writing-translations","link":"#writing-translations","children":[]},{"level":2,"title":"Deleting Translations","slug":"deleting-translations","link":"#deleting-translations","children":[]},{"level":2,"title":"Checking Translations","slug":"checking-translations","link":"#checking-translations","children":[]},{"level":2,"title":"Locale Context","slug":"locale-context","link":"#locale-context","children":[]},{"level":2,"title":"Query Scopes","slug":"query-scopes","link":"#query-scopes","children":[{"level":3,"title":"Base Value Fallback Scopes","slug":"base-value-fallback-scopes","link":"#base-value-fallback-scopes","children":[]}]},{"level":2,"title":"Eager Loading","slug":"eager-loading","link":"#eager-loading","children":[]},{"level":2,"title":"JSON and Array Attributes","slug":"json-and-array-attributes","link":"#json-and-array-attributes","children":[]},{"level":2,"title":"File Attachments","slug":"file-attachments","link":"#file-attachments","children":[{"level":3,"title":"Reading Translated Files","slug":"reading-translated-files","link":"#reading-translated-files","children":[]},{"level":3,"title":"Writing Translated Files","slug":"writing-translated-files","link":"#writing-translated-files","children":[]},{"level":3,"title":"Checking and Deleting Translated Files","slug":"checking-and-deleting-translated-files","link":"#checking-and-deleting-translated-files","children":[]},{"level":3,"title":"Translating Files in the Backend","slug":"translating-files-in-the-backend","link":"#translating-files-in-the-backend","children":[]},{"level":3,"title":"How Files Are Stored","slug":"how-files-are-stored","link":"#how-files-are-stored","children":[]},{"level":3,"title":"Translating File Titles and Descriptions","slug":"translating-file-titles-and-descriptions","link":"#translating-file-titles-and-descriptions","children":[]}]},{"level":2,"title":"Method Reference","slug":"method-reference","link":"#method-reference","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/multisite/translatable.md","filePath":"4.x/extend/multisite/translatable.md"}'),r={name:"4.x/extend/multisite/translatable.md"};function u(d,a,k,g,h,f){const t=s("pre-heading"),e=s("post-heading");return l(),p("div",null,[n(t),a[0]||(a[0]=c("h1",null,"Translatable",-1)),n(e),a[1]||(a[1]=i(`<div class="custom-block aside"><p>For an overview of when to use this trait versus Multisite or MultisiteGroup, see the <a href="./introduction.html">Introduction</a>.</p></div><p>Translatable models store translated attribute values in a separate table, with one row per model, per attribute, per locale. The active locale is resolved automatically from the <code>Site</code> facade. To make attributes translatable, apply the <code>October\\Rain\\Database\\Traits\\Translatable</code> trait and declare a <code>$translatable</code> property with an array containing the attributes to translate.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Translatable</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$translatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;description&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;slug&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The trait automatically registers a <code>translations</code> morphMany relationship and stores translations in the <code>system_translate_attributes</code> table.</p><h2 id="how-it-works"><a href="#how-it-works" class="header-anchor">#</a> How It Works</h2><p>When the active site locale differs from the default locale, the trait intercepts <code>getAttribute</code> and <code>setAttribute</code> to read and write translated values instead of model attributes. When only one locale exists (or the default locale is active), the trait is invisible — no extra queries, no relationship loading, just a single string comparison on every attribute access.</p><p>Translated values are stored in the <code>system_translate_attributes</code> table:</p><div class="language- extra-class"><pre class="language-text"><code>| model_type | model_id | locale | attribute | value   |
|------------|----------|--------|-----------|---------|
| Product    | 42       | fr     | name      | Produit |
| Product    | 42       | fr     | slug      | produit |
| Product    | 42       | de     | name      | Produkt |
</code></pre></div><h2 id="reading-translations"><a href="#reading-translations" class="header-anchor">#</a> Reading Translations</h2><p>Translated values are returned automatically based on the active site locale when accessing model attributes.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span> <span class="token comment">// Returns translated value or falls back to default</span>
</code></pre></div><p>Use the <code>getTranslation</code> method to read a translation for a specific locale.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>By default, if no translation exists for the requested locale, the method falls back to the default locale value. To disable fallback and return <code>null</code> instead, pass <code>false</code> as the third argument.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token argument-name">useFallback</span><span class="token punctuation">:</span> <span class="token constant boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>getTranslations</code> method to get all locale values for a single attribute.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getTranslations</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// Returns: [&#39;en&#39; =&gt; &#39;Product&#39;, &#39;fr&#39; =&gt; &#39;Produit&#39;, &#39;de&#39; =&gt; &#39;Produkt&#39;]</span>
</code></pre></div><h2 id="writing-translations"><a href="#writing-translations" class="header-anchor">#</a> Writing Translations</h2><p>Translations are written automatically when the active locale is set and the model is saved.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Produit&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>setTranslation</code> method to set a translation for a specific locale. The model must be saved afterward.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Produit&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>setTranslations</code> method to set multiple locales at once for a single attribute.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setTranslations</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;fr&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Produit&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;de&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Produkt&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>For non-default locales, attributes whose value matches the default locale value are not stored. They inherit from the model table via fallback, so changes to the default automatically propagate to untranslated locales.</p></div><h2 id="deleting-translations"><a href="#deleting-translations" class="header-anchor">#</a> Deleting Translations</h2><p>Use the <code>forgetTranslation</code> method to remove a single translation.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">forgetTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>forgetTranslations</code> method to remove all translations for an attribute across all locales.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">forgetTranslations</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>forgetAllTranslations</code> method to remove all translations for a locale, effectively &quot;unpublishing&quot; that language.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">forgetAllTranslations</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="checking-translations"><a href="#checking-translations" class="header-anchor">#</a> Checking Translations</h2><p>Use the <code>hasTranslation</code> method to check if a specific attribute has been translated.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">hasTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true or false</span>
</code></pre></div><p>Use the <code>hasTranslations</code> method to check if the model has any translations at all for a given locale.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">hasTranslations</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true if ANY attribute has a translation for &#39;fr&#39;</span>
</code></pre></div><p>Use the <code>getTranslatedLocales</code> method to get a list of locales that have translations. Pass an attribute name to check locales for a specific attribute.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getTranslatedLocales</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [&#39;fr&#39;, &#39;de&#39;]</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getTranslatedLocales</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [&#39;fr&#39;, &#39;de&#39;]</span>
</code></pre></div><h2 id="locale-context"><a href="#locale-context" class="header-anchor">#</a> Locale Context</h2><p>Use the <code>setLocale</code> method to override the locale for a model instance. This affects how <code>getAttribute</code> and <code>setAttribute</code> behave.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span> <span class="token comment">// Returns French translation</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getLocale</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// &#39;fr&#39;</span>
</code></pre></div><p>The <code>setLocale</code> method is chainable.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="query-scopes"><a href="#query-scopes" class="header-anchor">#</a> Query Scopes</h2><p>Use the <code>whereTranslation</code> scope to filter by translated attribute values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">whereTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Produit&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The scope also supports a fourth argument for the comparison operator.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">whereTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;%Prod%&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;like&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>orderByTranslation</code> scope to sort by translated attribute values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">orderByTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;asc&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="base-value-fallback-scopes"><a href="#base-value-fallback-scopes" class="header-anchor">#</a> Base Value Fallback Scopes</h3><p>The <code>whereTranslation</code> and <code>orderByTranslation</code> scopes match and sort against stored translation rows only, so records with no translation for the requested locale are excluded from a <code>where</code> and sort as <code>NULL</code> in an order. When you want untranslated records to fall back to their default-locale value instead, use the <code>transWhere</code> and <code>transOrderBy</code> scopes.</p><p>Use the <code>transWhere</code> scope to filter by either the base value or the translated value for the locale. The locale defaults to the active locale when omitted.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">transWhere</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Produit&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Like <code>whereTranslation</code>, it accepts a comparison operator.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">transWhere</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;%Prod%&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;like&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>transOrderBy</code> scope to sort by the translated value, falling back to the base column value for untranslated records. The locale defaults to the active locale when omitted.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">transOrderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;asc&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="eager-loading"><a href="#eager-loading" class="header-anchor">#</a> Eager Loading</h2><p>Use the <code>withTranslation</code> scope to eager load translations for a single locale, avoiding N+1 queries.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">withTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When called without arguments, it uses the current site locale.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">withTranslation</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>withTranslations</code> scope to eager load all translations for all locales.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">withTranslations</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can also use standard Eloquent eager loading with the <code>translations</code> relationship.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;translations&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="json-and-array-attributes"><a href="#json-and-array-attributes" class="header-anchor">#</a> JSON and Array Attributes</h2><p>Attributes declared as <code>$jsonable</code> on the model are handled transparently. Array values are serialized to JSON when stored in the translation table and deserialized back to arrays when read.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Translatable</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$translatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;options&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;options&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;options&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;color&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;rouge&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;options&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [&#39;color&#39; =&gt; &#39;rouge&#39;]</span>
</code></pre></div><h2 id="file-attachments"><a href="#file-attachments" class="header-anchor">#</a> File Attachments</h2><p>To give each locale its own files, apply the <code>October\\Rain\\Database\\Traits\\TranslatableAttachments</code> trait alongside the <code>Translatable</code> trait, then add the name of an <code>$attachOne</code> or <code>$attachMany</code> relation to the <code>$translatable</code> property. Attachment relations not listed in <code>$translatable</code> are shared by every locale.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Product</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Translatable</span><span class="token punctuation">;</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>TranslatableAttachments</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$translatable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;gallery&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;image&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;manual&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;gallery&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>In the example above, the <code>image</code> and <code>gallery</code> relations store their files per locale, while the <code>manual</code> file is the same for every locale. Without the <code>TranslatableAttachments</code> trait, attachment relations listed in <code>$translatable</code> are shared by every locale.</p><h3 id="reading-translated-files"><a href="#reading-translated-files" class="header-anchor">#</a> Reading Translated Files</h3><p>Accessing the relation as a property returns the files for the active locale. When the locale has no files of its own, the files for the default locale are returned instead.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">image</span><span class="token punctuation">;</span> <span class="token comment">// French image, or the default image when there is none</span>
</code></pre></div><p>The fallback applies to the whole relation. When a locale has its own files for an <code>$attachMany</code> relation, only those files are returned and the default files are not merged in. For example, if the default gallery has six images and the French gallery has one, the French gallery contains one image.</p><p>Eager loading and relation queries such as <code>has</code> and <code>withCount</code> use the same fallback, so each record resolves to its own locale files or the default files.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">with</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;gallery&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name static-context">Product</span><span class="token operator">::</span><span class="token function">withCount</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;gallery&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Querying the relation method directly returns only the files stored for the active locale, without the fallback. Use this when you need to know which files a locale has of its own.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">gallery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Only the French files</span>
</code></pre></div><h3 id="writing-translated-files"><a href="#writing-translated-files" class="header-anchor">#</a> Writing Translated Files</h3><p>Files are added for the active locale. Set the locale on the model, then assign or add files the same way as an untranslated attachment.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">image</span> <span class="token operator">=</span> <span class="token variable">$uploadedFile</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">setLocale</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">gallery</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$file</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Adding a file for one locale never changes the files of another locale. Replacing the French image of an <code>$attachOne</code> relation removes the previous French image and keeps the default image.</p><h3 id="checking-and-deleting-translated-files"><a href="#checking-and-deleting-translated-files" class="header-anchor">#</a> Checking and Deleting Translated Files</h3><p>Use the <code>hasAttachmentTranslation</code> method to check if a locale has files of its own, and the <code>getTranslatedAttachmentLocales</code> method to list the locales that do. The locale defaults to the active locale when omitted.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">hasAttachmentTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true if French has its own image</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">getTranslatedAttachmentLocales</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// [&#39;fr&#39;, &#39;de&#39;]</span>
</code></pre></div><p>Use the <code>forgetAttachmentTranslation</code> method to remove the files for a locale. The locale then falls back to the default files again.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">forgetAttachmentTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use the <code>forgetAttachmentTranslations</code> method to remove the files for every locale except the default locale.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token function">forgetAttachmentTranslations</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>The record-level methods of the <code>Translatable</code> trait, such as <code>hasTranslations</code>, <code>getTranslatedLocales</code> and <code>forgetAllTranslations</code>, only consider attribute translations. Call the attachment methods for each name returned by <code>getTranslatableAttachments</code> to include files.</p></div><p>When the record is deleted, the files for every locale are deleted with it, or detached when the relation definition sets <code>delete</code> to <code>false</code>. Soft deleted records keep their files so they can be restored.</p><h3 id="translating-files-in-the-backend"><a href="#translating-files-in-the-backend" class="header-anchor">#</a> Translating Files in the Backend</h3><p>File upload fields for translated attachments show the translate icon like other translatable fields. Click the icon and select a site to upload or remove the files for that locale in a popup, then click <strong>Save</strong> to keep the changes. Closing the popup without saving discards the uploads. Files can also be translated by switching the site using the site selector and uploading them in the main form.</p><p>In a non-default locale, the file upload field lists only the files of that locale, and an empty field means the default files are used.</p><h3 id="how-files-are-stored"><a href="#how-files-are-stored" class="header-anchor">#</a> How Files Are Stored</h3><p>Translated files are stored in the <code>system_files</code> table along with every other attachment. The locale is added to the <code>field</code> column, while files for the default locale are stored without a suffix, the same as an untranslated attachment.</p><div class="language- extra-class"><pre class="language-text"><code>| attachment_type | attachment_id | field    | file_name    |
|-----------------|---------------|----------|--------------|
| Product         | 42            | image    | product.jpg  |
| Product         | 42            | image:fr | produit.jpg  |
| Product         | 42            | image:de | produkt.jpg  |
</code></pre></div><p>Since the default files are stored without a suffix, adding an existing relation to <code>$translatable</code> keeps its current files as the default files, with no migration required.</p><div class="custom-block tip"><p>Each locale stores its own file records, so the file title and description can already be different for each locale.</p></div><h3 id="translating-file-titles-and-descriptions"><a href="#translating-file-titles-and-descriptions" class="header-anchor">#</a> Translating File Titles and Descriptions</h3><p>A file shared by every locale can still have its title and description translated. Use the <code>System\\Models\\TranslatableFile</code> model in the relation definition instead of <code>System\\Models\\File</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;manual&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>TranslatableFile</span><span class="token operator">::</span><span class="token keyword">class</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>The title and description are translated like any other translatable attribute, and fall back to the default locale when there is no translation. The file reads its locale from the active site, so calling <code>setLocale</code> on the parent model does not change it. Call <code>setLocale</code> on the file instead.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">manual</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">;</span> <span class="token comment">// Title in the active locale</span>

<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">manual</span><span class="token operator">-&gt;</span><span class="token function">setTranslation</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;fr&#39;</span><span class="token punctuation">,</span> <span class="token string double-quoted-string">&quot;Guide d&#39;utilisation&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$product</span><span class="token operator">-&gt;</span><span class="token property">manual</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>In the backend, the title and description fields show the translate icon when editing the details of the file.</p><p>The <code>TranslatableFile</code> model works on any model, including models without the <code>Translatable</code> trait. Switching a relation between <code>File</code> and <code>TranslatableFile</code> requires no migration, since the model class is not stored with the file.</p><h2 id="method-reference"><a href="#method-reference" class="header-anchor">#</a> Method Reference</h2><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>getTranslation($key, $locale, $useFallback = true)</code></td><td>Get translated value for attribute and locale.</td></tr><tr><td><code>setTranslation($key, $locale, $value)</code></td><td>Set translated value for attribute and locale.</td></tr><tr><td><code>getTranslations($key)</code></td><td>Get all locale values for an attribute.</td></tr><tr><td><code>setTranslations($key, array $translations)</code></td><td>Set multiple locales at once.</td></tr><tr><td><code>hasTranslation($key, $locale = null)</code></td><td>Check if a translation row exists for one attribute.</td></tr><tr><td><code>hasTranslations($locale = null)</code></td><td>Check if any translation rows exist for the locale (record-level).</td></tr><tr><td><code>getTranslatedLocales($key = null)</code></td><td>Get locales with translations.</td></tr><tr><td><code>forgetTranslation($key, $locale)</code></td><td>Delete a single translation row.</td></tr><tr><td><code>forgetTranslations($key)</code></td><td>Delete all translation rows for an attribute.</td></tr><tr><td><code>forgetAllTranslations($locale)</code></td><td>Delete all translation rows for a locale.</td></tr><tr><td><code>setLocale($locale)</code></td><td>Override the locale context for this instance.</td></tr><tr><td><code>getLocale()</code></td><td>Get the active locale.</td></tr><tr><td><code>isTranslatableAttribute($key)</code></td><td>Check if attribute should be translated right now.</td></tr><tr><td><code>shouldTranslate()</code></td><td>Check if translation is active (context !== default).</td></tr><tr><td><code>getTranslatableAttributes()</code></td><td>Get the <code>$translatable</code> attribute names.</td></tr><tr><td><code>whereTranslation($key, $locale, $value, $operator = &#39;=&#39;)</code></td><td>Filter by a stored translated value only.</td></tr><tr><td><code>orderByTranslation($key, $locale, $direction = &#39;asc&#39;)</code></td><td>Sort by a stored translated value (untranslated rows sort as <code>NULL</code>).</td></tr><tr><td><code>transWhere($key, $value, $locale = null, $operator = &#39;=&#39;)</code></td><td>Filter by the base or translated value, defaulting to the active locale.</td></tr><tr><td><code>transOrderBy($key, $direction = &#39;asc&#39;, $locale = null)</code></td><td>Sort by the translated value, falling back to the base value.</td></tr></tbody></table></div><p>The <code>TranslatableAttachments</code> trait adds the following methods.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>getTranslatableAttachments()</code></td><td>Get the <code>$translatable</code> names that are file attachment relations.</td></tr><tr><td><code>hasAttachmentTranslation($key, $locale = null)</code></td><td>Check if a locale has files of its own for an attachment.</td></tr><tr><td><code>getTranslatedAttachmentLocales($key)</code></td><td>Get the non-default locales with files of their own for an attachment.</td></tr><tr><td><code>forgetAttachmentTranslation($key, $locale)</code></td><td>Delete the files of a locale for an attachment.</td></tr><tr><td><code>forgetAttachmentTranslations($key)</code></td><td>Delete the files of every non-default locale for an attachment.</td></tr></tbody></table></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./introduction.html">Introduction</a></li><li><a href="./multisite.html">Multisite Trait</a></li><li><a href="./multisite-group.html">MultisiteGroup Trait</a></li><li><a href="./../../cms/multisite/tailor.html">Tailor Localization</a></li></ul></div>`,118))])}const b=o(r,[["render",u]]);export{v as __pageData,b as default};
